"""Sequential batch-job runner implementing Meridian CRM error semantics."""

from collections.abc import Callable
from typing import Any


def run_jobs(
    jobs: list[dict],
    executor: Callable[[dict], Any],
) -> list[dict]:
    """Execute scheduled jobs sequentially and return an attempt log."""
    run_log: list[dict] = []

    for job in jobs:
        policy = job["on_error"]["policy"]
        retries = job["on_error"]["retries"]
        max_attempts = retries + 1 if policy == "RETRY" else 1
        attempts = 0
        succeeded = False

        while attempts < max_attempts:
            attempts += 1
            try:
                executor(job)
            except Exception:
                continue
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
